-- Series 22: add the 6 non-PTFE seat materials (360 new quote-only products).
-- Run AFTER seed_series_22_info.sql + seed_series_22_products.sql. Run from file.
DECLARE @SeriesName nvarchar(100) = N'Series 22';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

-- 1) Seat Material filter + attach to Series 22
INSERT INTO Filters (Name) SELECT N'Seat Material' WHERE NOT EXISTS (SELECT 1 FROM Filters WHERE Name=N'Seat Material');
INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, 4 FROM Filters f WHERE f.Name=N'Seat Material'
  AND NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

-- 2) Backfill Seat Material = PTFE onto the existing 60 priced products
INSERT INTO ProductFilterValues (ProductId, CategoryId, FilterId, Value)
SELECT p.ProductId, p.CategoryId, f.FilterId, N'PTFE'
FROM CatalogProducts p CROSS JOIN Filters f
WHERE p.CategoryId=@CategoryId AND f.Name=N'Seat Material'
  AND NOT EXISTS (SELECT 1 FROM ProductFilterValues v WHERE v.ProductId=p.ProductId AND v.FilterId=f.FilterId);

-- 3) New products (no price -> NULL)
